<span class="line"><span style="color:#383A42;">    console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;Name: &quot;</span><span style="color:#0184BC;"> +</span><span style="color:#383A42;"> privateVar);</span></span>
